import * as React from "react";
import { cx } from "./cx";

export interface SidebarProps extends React.HTMLAttributes<HTMLElement> {}

/** One 204 module rail. Flush items, hairline edge. */
export function Sidebar({ className, ...props }: SidebarProps) {
  return <aside className={cx("rs-sidebar", className)} {...props} />;
}

export function SidebarHead({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cx("rs-sidebar-head", className)} {...props} />;
}

export function SidebarNav({ className, ...props }: React.HTMLAttributes<HTMLElement>) {
  return <nav className={cx("rs-sidebar-nav", className)} {...props} />;
}

export interface SidebarItemProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  current?: boolean;
}

export function SidebarItem({ current, className, ...props }: SidebarItemProps) {
  return (
    <a className={cx("rs-sidebar-item", className)} aria-current={current ? "page" : undefined} {...props} />
  );
}

export function SidebarLabel({ className, ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
  return <p className={cx("rs-sidebar-label", className)} {...props} />;
}

export function SidebarFoot({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cx("rs-sidebar-foot", className)} {...props} />;
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Sidebar: one 204 module rail, flush items, hairline edge.
   Last item keeps air before the foot rule. ── */
.rs-sidebar{width:204px;min-height:204px;display:flex;flex-direction:column;border-right:1px solid var(--divider);background:var(--bg);border-radius:0}
.rs-sidebar-head{padding:16px 20px;font-size:13px;font-weight:600;letter-spacing:-.01em;color:var(--text);border-bottom:1px solid var(--divider)}
.rs-sidebar-nav{display:flex;flex-direction:column;padding:8px 0 20px;flex:1}
.rs-sidebar-item,
.rs-sidebar-item:link,
.rs-sidebar-item:visited,
.rs-sidebar-item:any-link{
  display:block;
  padding:8px 20px;
  font-size:13px;
  font-weight:500;
  letter-spacing:-.01em;
  color:var(--text-secondary);
  text-decoration:none;
}
.rs-sidebar-item:last-child{padding-bottom:20px}
.rs-sidebar-item:hover,.rs-sidebar-item[aria-current="page"]{color:var(--text)}
.rs-sidebar-label{padding:16px 20px 4px;font-size:12px;font-weight:600;letter-spacing:-.01em;color:var(--text-secondary)}
.rs-sidebar-foot{padding:12px 20px;border-top:1px solid var(--divider);font-size:12px;font-weight:500;letter-spacing:-.01em;color:var(--text-secondary)}
